-- Generated from the app seed data. Paste this file into Supabase SQL Editor.
-- Run the table-creation SQL first. This is safe to run repeatedly.
BEGIN;
ON CONFLICT (competency_id) DO UPDATE SET
  competency_name = excluded.competency_name,
  sector = excluded.sector,
  qualification = excluded.qualification,
  status = excluded.status,
  updated_at = excluded.updated_at;

ON CONFLICT (module_id) DO UPDATE SET
  module_name = excluded.module_name,
  description = excluded.description,
  updated_at = excluded.updated_at;
ON CONFLICT (lesson_id) DO UPDATE SET
  lesson_name = excluded.lesson_name,
  order_number = excluded.order_number,
  updated_at = excluded.updated_at;

ON CONFLICT (lesson_content_id) DO UPDATE SET
  content_name = excluded.content_name,
  objectives = excluded.objectives,
  updated_at = excluded.updated_at;

ON CONFLICT (content_info_id) DO UPDATE SET
  lesson_content_id = excluded.lesson_content_id,
  label = excluded.label,
  description = excluded.description,
  updated_at = excluded.updated_at;
ON CONFLICT (instruct_id) DO UPDATE SET
  question_instruction = excluded.question_instruction,
  question_title = excluded.question_title,
  question_label = excluded.question_label,
  updated_at = excluded.updated_at;

ON CONFLICT (question_id) DO UPDATE SET
  question = excluded.question,
  question_type = excluded.question_type,
  question_order = excluded.question_order,
  updated_at = excluded.updated_at;

ON CONFLICT (choice_id) DO UPDATE SET
  choice_label = excluded.choice_label,
  choice_text = excluded.choice_text,
  is_correct = excluded.is_correct,
  updated_at = excluded.updated_at;

ON CONFLICT (job_id) DO UPDATE SET
  job_title = excluded.job_title,
  job_objectives = excluded.job_objectives,
  job_materials = excluded.job_materials,
  job_steps = excluded.job_steps,
  job_assesment_method = excluded.job_assesment_method,
  updated_at = excluded.updated_at;

ON CONFLICT (performance_id) DO UPDATE SET
  performance_question = excluded.performance_question,
  performance_order = excluded.performance_order,
  updated_at = excluded.updated_at;

ON CONFLICT (module_achievement_id) DO UPDATE SET
  module_id = excluded.module_id,
  name = excluded.name,
  updated_at = excluded.updated_at;
ON CONFLICT (lesson_achievement_id) DO UPDATE SET
  lesson_id = excluded.lesson_id,
  name = excluded.name,
  updated_at = excluded.updated_at;
COMMIT;
